// AdminDashboard.js - MODIFICATIONS CRITIQUES
import React, { useState } from 'react';
import { useAuthContext } from '../../hooks/useAuthContext';
import { useAdmin } from '../../hooks/UseAdmin';
import { useCourseContext } from '../../context/CourContext'; // ← IMPORT CONTEXTE
import './admindashboard.css';

const AdminDashboard = () => {
  const { user } = useAuthContext();
  const { isAdmin } = useAdmin();
  const { courses, addCourse, deleteCourse } = useCourseContext(); // ← UTILISEZ LE CONTEXTE
  
  const [activeTab, setActiveTab] = useState('overview');
  const [showNewCourseForm, setShowNewCourseForm] = useState(false);
  const [newCourse, setNewCourse] = useState({
    title: '',
    category: '',
    instructor: '',
    price: '',
    description: '',
    status: 'draft'
  });

  // SUPPRIMEZ le state local des cours :
  // const [courses, setCourses] = useState([...]); ← À SUPPRIMER

  // MODIFIEZ handleSubmitCourse pour utiliser le contexte :
  const handleSubmitCourse = (e) => {
    e.preventDefault();
    
    const courseData = {
      title: newCourse.title,
      category: newCourse.category,
      instructor: newCourse.instructor,
      price: parseInt(newCourse.price),
      description: newCourse.description,
      status: newCourse.status,
      // Les autres champs seront ajoutés automatiquement par addCourse
      rating: 4.5,
      students: 0,
      duration: "10h 00min", 
      level: "Intermédiaire",
      featured: false,
      originalPrice: Math.round(parseInt(newCourse.price) * 1.5),
      image: "/images/default-course.jpg"
    };

    // Utilisez la fonction du contexte
    addCourse(courseData);
    
    // Réinitialiser le formulaire
    setNewCourse({
      title: '',
      category: '',
      instructor: '',
      price: '',
      description: '',
      status: 'draft'
    });
    
    setShowNewCourseForm(false);
    alert('✅ Cours créé avec succès !');
  };

  // MODIFIEZ handleDeleteCourse pour utiliser le contexte :
  const handleDeleteCourse = (courseId) => {
    if (window.confirm('Êtes-vous sûr de vouloir supprimer ce cours ?')) {
      deleteCourse(courseId); // ← Utilisez la fonction du contexte
      alert('✅ Cours supprimé avec succès !');
    }
  };

  // ... le reste du code reste identique

  return (
    <div className="admin-dashboard">
      {/* Le JSX reste exactement le même */}
      {/* Le tableau utilisera maintenant les cours du contexte */}
    </div>
  );
};

export default AdminDashboard;
